  "NAUČÍME ŤA TO,<br><span class=\"mark\">ČO ROBÍME MY</span>": "НАВЧИМО ТЕБЕ ТОГО,<br><span class=\"mark\">ЩО РОБИМО САМІ</span>",
  "NEALKOHOLICKÉ<br><span class=\"mark\">NÁPOJE</span>": "БЕЗАЛКОГОЛЬНІ<br><span class=\"mark\">НАПОЇ</span>",
