  "PRÉMIOVÁ SHISHA<br><span class=\"mark\">V SRDCI TRNAVY</span>": "ПРЕМІАЛЬНІ КАЛЬЯНИ<br><span class=\"mark\">У СЕРЦІ ТРНАВИ</span>",
  "Panini alebo sandwich na tanieri": "Паніні або сендвіч на тарілці",
