  "UVIDÍME SA<br><span class=\"mark\">DNES VEČER?</span>": "ПОБАЧИМОСЯ<br><span class=\"mark\">СЬОГОДНІ ВВЕЧЕРІ?</span>",
  "Uhlíky": "Вугілля",
